<div class="page-heading"><div><p class="eyebrow">DATEISUCHE</p><h1><?= $e($data['space']['name']) ?></h1><p class="lead">Dateien und Ordner nach Namen finden.</p></div><a href="<?= $e('/files?' . http_build_query(['space' => $data['space']['id']])) ?>">Zum Speicherbereich</a></div>
<p class="view-switch"><strong>Dateien und Ordner nach Namen</strong><?php if($data['can_catalog_read']??false): ?> · <a href="<?= $e('/catalog/search?'.http_build_query(['space'=>$data['space']['id'],'q'=>$data['search_text']])) ?>">Beschreibungen und Tags durchsuchen</a><?php endif ?></p>
<section class="panel auth-panel"><form method="get" action="/files/search"><input type="hidden" name="space" value="<?= $e($data['space']['id']) ?>"><label for="search-text">Name enthält</label><input id="search-text" name="q" value="<?= $e($data['search_text']) ?>" maxlength="128"><label for="search-kind">Eintragstyp</label><select id="search-kind" name="kind"><?php foreach (['all' => 'Dateien und Ordner', 'file' => 'Nur Dateien', 'folder' => 'Nur Ordner'] as $key => $label): ?><option value="<?= $e($key) ?>"<?= $data['search_kind'] === $key ? ' selected' : '' ?>><?= $e($label) ?></option><?php endforeach ?></select><button class="button" type="submit">Suchen</button><p class="field-note">Alle sichtbaren Ordner dieses Bereichs. Groß-/Kleinschreibung wird ignoriert. Sonderzeichen werden wörtlich gesucht; Dateiinhalte und Papierkorb sind ausgeschlossen.</p></form></section>
<section class="panel"><div class="panel-heading"><h2>Ergebnisse</h2><span class="subtle">Bis zu 100 Einträge pro Seite</span></div><div class="group-list">
<?php foreach ($data['rows'] as $row): ?><article class="group-row"><div><h3><a href="<?= $e('/files/detail?' . http_build_query(['space' => $data['space']['id'], 'entry' => $row['id']])) ?>"><?= $e($row['name']) ?></a></h3><p><?= $e($row['folder_path'] === '' ? 'Bereichswurzel' : $row['folder_path']) ?> · <?= $row['kind'] === 'folder' ? 'Ordner' : $e(number_format((int) $row['size_bytes'], 0, ',', '.')) . ' Bytes' ?></p><a href="<?= $e('/files?' . http_build_query(['space' => $data['space']['id'], 'parent' => $row['parent_id']])) ?>">Enthaltenden Ordner öffnen</a></div><?php if ($row['kind'] === 'file' && $data['can_read']): ?><a class="button button-outline" href="<?= $e('/files/download?' . http_build_query(['space' => $data['space']['id'], 'entry' => $row['id']])) ?>">Herunterladen</a><?php endif ?></article><?php endforeach ?>
<?php if ($data['rows'] === []): ?><p class="empty">Keine passenden Einträge gefunden.</p><?php endif ?></div>
<?php if ($data['next'] !== null): ?><div class="panel-foot"><a href="<?= $e('/files/search?' . http_build_query(['space' => $data['space']['id'], 'q' => $data['search_text'], 'kind' => $data['search_kind'], 'after' => $data['next']])) ?>">Weitere Ergebnisse</a></div><?php endif ?></section>

